style:
/* 双影 —— 白底通栏页眉，左侧窄栏收拢信息，右侧主栏专注履历 */

.tw-shuangying.layout-sidebar.resume-paper.layout-sidebar {
  padding-top: 15mm;
}

.tw-shuangying.layout-sidebar.resume-paper .paper-header {
  margin: 0 0 7mm;
  padding: 0 0 4.6mm;
  background: none;
  border-bottom: 0.3mm solid #dfe4e8;
  color: #1f2933;
  print-color-adjust: exact;
}

.tw-shuangying.layout-sidebar.resume-paper .paper-header--photo {
  align-items: flex-start;
  gap: 8mm;
}

.tw-shuangying.layout-sidebar.resume-paper .paper-photo {
  order: 3;
  width: 26mm;
  height: 35mm;
  border: 0.4mm solid #dde3e7;
  border-radius: 0;
  box-shadow: none;
}

.tw-shuangying.layout-sidebar.resume-paper .paper-photo--monogram {
  display: grid;
  place-items: center;
  background: #f4f6f7;
  color: #5b6a74;
  font-size: calc(var(--paper-base-size) * 2.1);
  font-weight: 700;
}

.tw-shuangying.layout-sidebar.resume-paper .paper-name {
  color: #17222b;
  font-family: var(--paper-font-family);
  font-size: calc(var(--paper-base-size) * 2.25);
  letter-spacing: 0.06em;
}

.tw-shuangying.layout-sidebar.resume-paper .paper-identity {
  padding: 0;
  border: none;
  color: #74838d;
  font-size: calc(var(--paper-base-size) * 0.84);
}

.tw-shuangying.layout-sidebar.resume-paper .paper-role {
  margin-top: 2mm;
  color: #45535d;
  font-size: calc(var(--paper-base-size) * 0.94);
  font-weight: 400;
  line-height: 1.6;
}

.tw-shuangying.layout-sidebar.resume-paper .paper-contacts {
  margin-top: 3mm;
  color: #46555f;
  font-size: calc(var(--paper-base-size) * 0.86);
  gap: 1.2mm 7mm;
}

.tw-shuangying.layout-sidebar.resume-paper .paper-contact__label {
  color: #7d8c96;
}

/* 主栏标题只留自己画的粗线，不要内置圆徽 */
.tw-shuangying.layout-sidebar.resume-paper .sidebar-main .paper-section__icon {
  display: none;
}

/* 窄栏放左，主栏放右 */
.tw-shuangying.layout-sidebar.resume-paper .sidebar-layout {
  grid-template-columns: 50mm minmax(0, 1fr);
  column-gap: 8mm;
}

.tw-shuangying.layout-sidebar.resume-paper .sidebar-aside {
  grid-column: 1;
  padding: 0 8mm 0 0;
  background: none;
  border-top: none;
  border-right: 0.25mm solid #e3e7ea;
}

.tw-shuangying.layout-sidebar.resume-paper .sidebar-main {
  grid-column: 2;
}

.tw-shuangying.layout-sidebar.resume-paper .sidebar-aside .paper-section__title {
  display: block;
  margin-bottom: 2.4mm;
  padding: 0 0 1.2mm;
  border: none;
  border-bottom: 0.25mm solid #dfe4e8;
  color: #2a363f;
  font-size: calc(var(--paper-base-size) * 0.94);
  letter-spacing: 0.14em;
}

.tw-shuangying.layout-sidebar.resume-paper .sidebar-aside .paper-section__icon {
  display: none;
}

.tw-shuangying.layout-sidebar.resume-paper .sidebar-main .paper-section__title {
  display: flex;
  align-items: center;
  gap: 2.4mm;
  margin-bottom: 3mm;
  padding-bottom: 1.4mm;
  border-bottom: 0.4mm solid #2a3640;
  color: #1d2831;
  font-size: calc(var(--paper-base-size) * 1.06);
  letter-spacing: 0.12em;
}

.tw-shuangying.layout-sidebar.resume-paper .sidebar-main .paper-section__title::before {
  content: "";
  width: 1.6mm;
  height: 3.4mm;
  background: #2a3640;
  print-color-adjust: exact;
}

.tw-shuangying.layout-sidebar.resume-paper .paper-section__body {
  color: #333f48;
}

.tw-shuangying.layout-sidebar.resume-paper .paper-item-title {
  color: #1b262f;
}

.tw-shuangying.layout-sidebar.resume-paper .paper-item-period {
  color: #77848d;
  font-size: calc(var(--paper-base-size) * 0.86);
}

.tw-shuangying.layout-sidebar.resume-paper .paper-item-sub {
  color: #46545e;
}

.tw-shuangying.layout-sidebar.resume-paper .paper-rich ul,
.tw-shuangying.layout-sidebar.resume-paper .paper-rich ol {
  margin-top: 0.8mm;
  padding-left: 0;
  list-style: none;
}

.tw-shuangying.layout-sidebar.resume-paper .paper-rich li {
  position: relative;
  margin: 0.7mm 0;
  padding-left: 3.4mm;
}

.tw-shuangying.layout-sidebar.resume-paper .paper-rich li::before {
  content: "";
  position: absolute;
  top: 0.7em;
  left: 0.4mm;
  width: 1mm;
  height: 1mm;
  border-radius: 50%;
  background: #96a3ac;
  print-color-adjust: exact;
}

.tw-shuangying.layout-sidebar.resume-paper .paper-skills {
  grid-template-columns: minmax(0, 1fr);
  gap: 1.4mm;
}

.tw-shuangying.layout-sidebar.resume-paper .paper-skill {
  padding-bottom: 0.6mm;
  border-bottom: none;
}

.tw-shuangying.layout-sidebar.resume-paper .paper-skill__name {
  font-size: calc(var(--paper-base-size) * 0.9);
}

.tw-shuangying.layout-sidebar.resume-paper .paper-note__tag {
  color: #1b262f;
  font-weight: 600;
}

.tw-shuangying.layout-sidebar.resume-paper .paper-footer {
  border-top: 0.2mm solid #e4e9ec;
  color: #9daab2;
}
